[CmdletBinding()]
param([string]$SkillRoot = (Join-Path (Get-Location) '.agents/skills/es-game-core-loop-validation'))
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $SkillRoot '..\..\..')).Path;$tmp=Join-Path $SkillRoot '.tmp-strict';New-Item -ItemType Directory -Force $tmp|Out-Null
try{$w=@{taskId='es.task-context.evaluate';status='Passed';inputManifestHash=('a'*64)}|ConvertTo-Json;$e=@{taskId='strict-fixture';recordType='EvaluationRecord';decisionScope='task-object';decision='accepted';evidenceState='observed'}|ConvertTo-Json;$wp=Join-Path $tmp 'worker.json';$ep=Join-Path $tmp 'evaluation.json';$rp=Join-Path $tmp 'receipt.json';[IO.File]::WriteAllText($wp,$w,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($ep,$e,[Text.UTF8Encoding]::new($false));& (Join-Path $SkillRoot 'scripts/Convert-ESGameCoreLoopWorkerEvidence.ps1') -WorkerResultPath $wp -EvaluationRecordPath $ep -TaskId strict-fixture -Layer structure -OutputPath $rp|Out-Null;& (Join-Path $SkillRoot 'scripts/Test-ESGameCoreLoopEvidence.ps1') -EvidencePath $rp -ProjectRoot $root|Out-Null;[ordered]@{status='passed';centralStrictReceipt='passed';runtimeStatus='runtime-not-run';deterministic=$true}|ConvertTo-Json}finally{Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue}
